"""Service settings: user values on top of defaults."""

from typing import Any

DEFAULTS: dict[str, Any] = {"timeout": 30, "retries": 3, "debug": False}


def load(user_settings: dict[str, Any]) -> dict[str, Any]:
    merged = dict(user_settings)
    return merged


def timeout(user_settings: dict[str, Any]) -> int:
    return int(load(user_settings)["timeout"])
